import {rememberSearch} from './history.mjs';
import {mountParsing,parsePanelHTML} from './parsing-ui.mjs';
import { createBrowserScanner } from './browser-scan.mjs?v=experience-2';
import { enrichReport } from './enrichment.mjs?v=sources-1';
const scanPlayer = createBrowserScanner();
document.querySelector('#loading .muted').textContent='Одна неудачная катка или привычка подводить команду? Смотрим на игру в целом — и готовим ответ.';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const publicText=s=>String(s||'').replace(/OpenDota|STRATZ|Dotabuff/gi,'анализа').replace(/IMP/g,'оценки вклада').replace(/Уже полученные матчи сохранены\.?|Полученные матчи сохранены\.?|загруженные матчи сохранены\.?/gi,'');
const n=(v,d=0)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:d}):'—';
const time=s=>`${Math.floor(Math.abs(s)/60)}:${String(Math.floor(Math.abs(s)%60)).padStart(2,'0')}`;
const date=s=>s?new Date(s*1000).toLocaleDateString('ru-RU'):'—';
let current,controller;
const roleNames={CORE:'Кор',SUPPORT:'Поддержка',SOFT_SUPPORT:'Поддержка',HARD_SUPPORT:'Полная поддержка',POSITION_1:'1 · Керри',POSITION_2:'2 · Мидер',POSITION_3:'3 · Офлейнер',POSITION_4:'4 · Поддержка',POSITION_5:'5 · Полная поддержка',SAFE_LANE:'Лёгкая линия',MID_LANE:'Центр',OFF_LANE:'Сложная линия',JUNGLE:'Лес',ROAMING:'Роуминг'};
const roleName=v=>v==null?'—':roleNames[v]||v;
function stratzMatchHTML(s){
  if(!s)return '<h3>Вклад в катку</h3><p class="muted">Дополнительные данные этого матча не получены.</p>';
  return `<h3>Роль и вклад в катку</h3><div class="chips"><span class="chip">Позиция: ${esc(roleName(s.position))}</span><span class="chip">Роль: ${esc(roleName(s.role))}</span><span class="chip">Линия: ${esc(roleName(s.lane))}</span><span class="chip">Оценка вклада: ${n(s.imp)}</span></div><p class="muted">Роль и линия определены автоматически. Положительная оценка вклада — игра лучше ожиданий, отрицательная — хуже. Она не доказывает намеренный руин.</p>${s.impPerMinute?.length?chart(s.impPerMinute,'Оценка вклада по минутам'):''}<details><summary>Смерти и обзор</summary>${s.deaths===null?'<p>Данные смертей из реплея недоступны.</p>':`<div class="table-wrap"><table><thead><tr><th>Время смерти</th><th>Потеря золота</th><th>Время мёртвым, сек.</th><th>Контекст</th></tr></thead><tbody>${s.deaths.map(d=>`<tr><td>${time(d.time)}</td><td>${n(d.goldLost)}</td><td>${n(d.timeDead)}</td><td>${d.isDieBack?'После выкупа. ':''}${d.isAttemptTpOut?'Попытка телепорта. ':''}</td></tr>`).join('')||'<tr><td colspan="4">Событий нет.</td></tr>'}</tbody></table></div>`}<p>Событий установки вардов: ${s.wards===null?'нет данных':n(s.wards.length)}. Координаты событий доступны в данных ниже; это не полный маршрут героя.</p><details><summary>Подробности событий</summary><pre>${esc(JSON.stringify(s,null,2))}</pre></details></details>`;
}
function sourcesHTML(r){
  const c=r.sourceComparison;
  if(!c)return '<section class="report-card"><h2>Вклад в катку</h2><p>Дополнительная оценка пока недоступна. Это не снижает результат игрока.</p></section>';
  return `<section class="report-card"><h2>Как игрок влияет на катку</h2><p>Оценка вклада показывает, насколько удачно игрок действовал относительно ожидаемого уровня игры. <b>Выше нуля — лучше ожиданий, ниже — хуже.</b> Это не процент побед и не доказательство намеренного руина.</p><div class="grid-stats"><div class="stat"><span>Средняя оценка вклада</span><strong>${n(c.mean,1)}</strong><small>Каток с оценкой: ${c.count}. Пропуски не заменяются нулями.</small></div><div class="stat"><span>Лучше / хуже ожиданий</span><strong>${c.positive} / ${c.negative}</strong><small>Количество каток с положительной и отрицательной оценкой. Нулевые оценки не входят в эти группы.</small></div></div><p class="note">${c.count<10?'Пока мало оценённых каток для уверенной сверки. Основной вывод опирается на доступные игровые показатели.':c.disagreement?'Игровые показатели и оценка вклада расходятся. Поэтому итог — «Смешанная картина».':'Оценка вклада дополняет общую картину. Одинаковые убийства и смерти не учитываются повторно.'}</p></section>`;
}
const descriptions={kills:['Убийства','Среднее за матч. Само по себе не определяет полезность.'],deaths:['Смерти','Среднее за матч; контекст и длительность важны.'],assists:['Помощь','Участие в убийствах союзников.'],gold_per_min:['GPM','Золото в минуту. Сильно зависит от роли.'],xp_per_min:['XPM','Опыт в минуту — темп набора уровней.'],hero_damage:['Урон героям','Средний суммарный урон за матч.'],tower_damage:['Урон строениям','Давление на объекты, а не только драки.'],hero_healing:['Лечение','Учтённое лечение за матч.'],last_hits:['Добивания','Число добитых крипов за матч.'],obs_placed:['Обсерверы','Поставленные варды; только доступные разборы.'],sen_placed:['Сентри','Поставленные сентри; не оценка качества обзора.'],camps_stacked:['Стаки лагерей','Созданные стаки по данным реплеев.'],stuns:['Контроль, сек.','Длительность оглушений по доступным событиям.']};
function chart(values,label){if(!Array.isArray(values)||!values.length)return '<p class="muted">Нет временного ряда.</p>';const valid=values.filter(v=>Number.isFinite(v));if(!valid.length)return '';const lo=Math.min(0,...valid),hi=Math.max(1,...valid),span=hi-lo||1;const points=values.map((v,i)=>Number.isFinite(v)?`${10+i/Math.max(1,values.length-1)*580},${145-(v-lo)/span*130}`:null).filter(Boolean).join(' ');return `<svg class="chart" viewBox="0 0 600 160" role="img" aria-label="${esc(label)}"><polyline fill="none" stroke="#d4aa68" stroke-width="2" points="${points}"/></svg><small>${esc(label)} · минимум ${n(Math.min(...valid))}, максимум ${n(Math.max(...valid))}; слева начало, справа конец.</small>`;}
function heatmap(pos){if(!pos||!Object.keys(pos).length)return '<p class="muted">Координаты линии недоступны.</p>';const points=Object.entries(pos).flatMap(([x,ys])=>Object.entries(ys).map(([y,v])=>({x:Number(x),y:Number(y),v:Number(v)}))).filter(p=>[p.x,p.y,p.v].every(Number.isFinite));const max=Math.max(1,...points.map(p=>p.v));return `<svg class="heatmap" viewBox="64 64 128 128" role="img" aria-label="Карта позиций на линии"><path d="M65 191L191 65" stroke="#38576b" stroke-width="1"/>${points.map(p=>`<circle cx="${p.x}" cy="${256-p.y}" r="1.8" fill="#efad64" opacity="${.15+.85*p.v/max}"/>`).join('')}</svg><p class="muted">Агрегированные позиции на стадии линии (lane_pos). Ярче — чаще фиксировался в этой точке. Это не полный маршрут и не оценка правильности перемещений.</p>`;}
function matchHTML(m){const p=m.player;return `<details class="match"><summary><b class="${m.win?'win':'loss'}">${m.win===null?'?':m.win?'ПОБЕДА':'ПОРАЖЕНИЕ'}</b><span class="match-head">${esc(m.hero)} · ${date(m.startTime)}</span><span>${n(p.kills)}/${n(p.deaths)}/${n(p.assists)}</span><small>${time(m.duration)} · ${m.parsed||m.stratz?.parsedAt?'Есть разбор реплея':'Базовые данные'}</small></summary><div class="match-body"><div class="chips"><span class="chip">Матч ${m.matchId}</span><span class="chip">GPM ${n(p.gold_per_min)}</span><span class="chip">XPM ${n(p.xp_per_min)}</span><span class="chip">Участие в убийствах ${n(m.killParticipation)}%</span><span class="chip">Режим ${n(m.mode)}</span><span class="chip">Линия ${n(p.lane_role)}</span></div>${m.unavailable?'<p class="note">Подробности матча не получены. В вердикте эта игра не оценивалась.</p>':''}${stratzMatchHTML(m.stratz)}<h3>Сравнение по герою</h3><div class="table-wrap"><table><thead><tr><th>Показатель</th><th>Значение</th><th>Процентиль</th></tr></thead><tbody>${m.metrics.map(x=>`<tr><td>${esc(x.label)}</td><td>${n(x.value,1)}</td><td>${n(x.percentile)} / 100</td></tr>`).join('')||'<tr><td colspan="3">Ориентиры недоступны</td></tr>'}</tbody></table></div><small>Процентиль — положение среди игроков на том же герое. Например, 70/100 — выше примерно 70% наблюдений. Рейтинг и роль могут отличаться.</small><h3>Эпизоды для просмотра</h3>${m.events.map(e=>`<div class="event"><b>${time(e.time)} · ${esc(e.title)}</b><p>${esc(e.text)}</p></div>`).join('')||'<p class="muted">По доступным данным подходящих эпизодов не выделено. Это не означает отсутствия ошибок.</p>'}<details><summary>Экономика по ходу игры</summary>${chart(p.gold_t,'Накопленное золото игрока')}${chart(m.goldAdvantage,'Преимущество Radiant по золоту (отрицательное — в пользу Dire)')}</details><details><summary>Позиции на линии</summary>${heatmap(p.lane_pos)}</details><details><summary>Покупки и тайминги</summary><div class="table-wrap"><table><tbody>${(p.purchase_log||[]).map(x=>`<tr><td>${x.time<0?'-':''}${time(x.time)}</td><td>${esc(x.key)}</td></tr>`).join('')||'<tr><td>Нет данных разобранного реплея.</td></tr>'}</tbody></table></div><small>Предметы обозначены игровыми именами.</small></details><details><summary>Командные драки (${m.fights.length})</summary><div class="table-wrap"><table><thead><tr><th>Время</th><th>Урон</th><th>Смерти</th><th>Изменение золота</th></tr></thead><tbody>${m.fights.map(f=>`<tr><td>${time(f.start)}</td><td>${n(f.damage)}</td><td>${n(f.deaths)}</td><td>${n(f.goldDelta)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>Все полученные показатели игрока</summary><pre>${esc(JSON.stringify(p,null,2))}</pre></details>${!m.parsed?'<p class="note">Для дополнительных подробностей нажми «Запросить разбор» в верхней части страницы. Доступность зависит от сохранности реплея.</p>':''}</div></details>`;}
function render(r){current=r;$('#loading').hidden=true;const c=r.coverage;$('#report').innerHTML=`<section class="report-card verdict ${esc(r.tone)}"><span class="eyebrow">ТВОЙ ТИММЕЙТ ПОД ЛУПОЙ</span><h1 class="report-title">${esc(r.verdict)}</h1><p>${esc(publicText(r.description))}</p><div class="profile-row"><strong>${esc(r.profile.personaname||`Игрок ${r.accountId}`)}</strong><span class="muted">Dota ID ${r.accountId}</span><a href="https://steamcommunity.com/profiles/${BigInt(r.accountId)+76561197960265728n}" target="_blank" rel="noopener">Steam ↗</a></div><div class="chips"><span class="chip">Подробности ${c.details}/${c.found}</span><span class="chip">С разбором реплея: ${r.matches.filter(m=>m.parsed||m.stratz?.parsedAt).length}</span><span class="chip">В оценке ${c.scored} игр</span><span class="chip">Победы ${n(r.winrate)}%</span></div><p class="muted">Сравнение по рейтингу пока недоступно. Вердикт основан на показателях по героям и может быть неточен для необычных ролей и стратегий.</p><div class="actions"><button id="download">Скачать отчёт JSON</button><button id="copy-link">Скопировать ссылку</button></div><p id="action-status" aria-live="polite"></p>${parsePanelHTML()}</section>${sourcesHTML(r)}<section class="report-card"><h2>Почему такой вывод</h2><p>Индекс ${n(r.score)}/100 — среднее доступных процентилей золота, опыта, урона героям, урона строениям и помощи. Только обычные игры длительностью от 15 минут с минимум тремя показателями. Это прозрачная эвристика, а не обученная модель.</p><div class="two-col">${r.comparisons.map(x=>`<div class="benchmark"><header><b>${esc(x.label)}</b><span>${n(x.percentile)}/100</span></header><div class="bar"><i style="width:${x.percentile??0}%"></i></div><small>Средний процентиль · игр с данными: ${x.samples}</small></div>`).join('')}</div></section><section class="report-card"><h2>Статистика серии</h2><div class="grid-stats">${Object.entries(r.aggregates).map(([k,v])=>`<div class="stat"><span>${descriptions[k][0]}</span><strong>${n(v.value,1)}</strong><small>${descriptions[k][1]}<br>Игр с данными: ${v.samples}</small></div>`).join('')}</div></section><section class="report-card"><h2>Последние игры</h2><p class="muted">Открой матч: показатели, тайминги, позиции и эпизоды. Недоступные значения обозначены «—».</p>${r.matches.map(matchHTML).join('')||'<p>Публичная история не найдена. Это не повод для негативного вердикта.</p>'}</section><section class="report-card"><h2>Как понимать результат</h2><ul>${r.limitations.map(x=>`<li>${esc(publicText(x))}</li>`).join('')}</ul><details><summary>Как выбирается вердикт</summary><p>Меньше 10 подходящих игр: недостаточно данных. Индекс ниже 30 и минимум 60% игр ниже 35: «Скрытопульный». Ниже 43: «Не в форме». Стандартное отклонение выше 18: «Нестабильный». Индекс от 72: «Тащит», от 58: «Надёжный тиммейт», иначе: «В пределах нормы». Пороги предварительные и требуют проверки на размеченных матчах.</p></details><small>Версия ${esc(r.version)} · данные собраны ${esc(new Date(r.generatedAt).toLocaleString('ru-RU'))}</small></section>`;
mountParsing(scanPlayer,r,{refresh:start,signal:controller.signal});
$('#download').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({player:current.accountId,verdict:current.verdict,description:publicText(current.description),statistics:current.aggregates,matches:current.matches.map(m=>({matchId:m.matchId,hero:m.hero,win:m.win,metrics:m.metrics,player:m.player,contribution:m.stratz?.imp??null}))},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`player-scan-${r.accountId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('#action-status').textContent='Ссылка скопирована.';}catch{$('#action-status').textContent='Скопируй адрес из строки браузера.';}};
}
async function start(){
  controller?.abort();controller=new AbortController();
  $('#failure').hidden=true;$('#loading').hidden=false;$('#report').innerHTML='';
  $('#retry').disabled=true;
  try{
    const input=new URLSearchParams(location.search).get('id');
    if(!input)throw new Error('В адресе нет Steam ID. Вернись на главную и введи профиль.');
    rememberSearch(input);
    const base=await scanPlayer(input,{signal:controller.signal,onProgress:(message,count)=>{
      $('#progress').textContent=count<1?'Собираем историю каток…':count<10?'Изучаем фарм, драки и помощь команде…':'Сопоставляем сильные стороны и повторяющиеся ошибки…';$('#progress-bar').value=count;
    }});
    const report=await enrichReport(base,{signal:controller.signal,onProgress:()=>$('#progress').textContent='Сверяем показатели и готовим вердикт…'});
    rememberSearch(input,report.profile.personaname);
    render(report);
  }catch(e){
    if(e.name==='AbortError')return;
    $('#loading').hidden=true;$('#failure').hidden=false;$('#failure-text').textContent=e.status===429?'Слишком много запросов. Подожди и попробуй позже.':publicText(e.message);
  }finally{$('#retry').disabled=false;}
}
$('#retry').onclick=start;start();
